471	// countTools estimates what the tool schemas cost on the wire.
472	//
473	// They are the last part of a request that /tokens could not see, and they are
474	// not small: nine tools with their descriptions and JSON Schema parameters are
475	// worth more than the system prompt on a fresh session. They also ride on
476	// *every* request, so a twelve-step turn pays for them twelve times.
477	//
478	// The envelope is mirrored from client.BuildBody rather than marshalling the
479	// ToolDefs directly, because the wire form wraps each one in
480	// {"type":"function","function":{…}} and counting the Go struct would
481	// under-report by that much on every tool. Duplicating four keys is the cheaper
482	// error: the alternative is for the coder to hold a client just to ask what a
483	// request weighs.
484	func (c *Coder) countTools() int {
485		defs := c.toolDefs()
486		if len(defs) == 0 {
487			return 0
488		}
489		wire := make([]map[string]any, len(defs))
490		for i, t := range defs {
491			wire[i] = map[string]any{
492				"type": "function",
493				"function": map[string]any{
494					"name": t.Name, "description": t.Description, "parameters": t.Parameters,
495				},
496			}
497		}
498		data, err := json.Marshal(wire)
499		if err != nil {
500			return 0
501		}
502		return c.Tokens.Count(string(data))
503	}
