505	// countMessages estimates the tokens a slice of messages will cost.
506	//
507	// Tool calls are counted, and that is not a refinement. m.Text() reads Content
508	// only, so an assistant message carrying nothing but tool calls counted as
509	// zero — and in this harness every action is a tool call, with an edit's
510	// old_string/new_string often the largest thing in the request. A twelve-step
511	// turn could report a few hundred tokens of history while sending several
512	// thousand. checkTokens counts the same way, so the guard that warns before a
513	// request overruns the declared window was blind to the same bytes.
514	//
515	// Still missing, deliberately for now: the tool *schemas*, which ride on every
516	// request and are worth on the order of a thousand tokens. They are a property
517	// of the request rather than of a message slice, so they belong in a row of
518	// their own rather than smuggled into this sum.
519	func (c *Coder) countMessages(msgs []llm.Message) int {
520		n := 0
521		for _, m := range msgs {
522			n += c.Tokens.Count(m.Text())
523			for _, tc := range m.ToolCalls {
524				n += c.Tokens.Count(tc.Name) + c.Tokens.Count(tc.Arguments)
525			}
526		}
527		return n
528	}
