535	func detectUserLanguage(explicit string) string {
536		if explicit != "" {
537			return normalizeLanguage(explicit)
538		}
539		for _, envVar := range []string{"LANG", "LANGUAGE", "LC_ALL", "LC_MESSAGES"} {
540			if v := os.Getenv(envVar); v != "" {
541				return normalizeLanguage(strings.SplitN(v, ".", 2)[0])
542			}
543		}
544		return ""
