553	func normalizeLanguage(code string) string {
554		if code == "" {
555			return ""
556		}
557		up := strings.ToUpper(code)
558		if up == "C" || up == "POSIX" {
559			return ""
560		}
561		if len(code) > 3 && !strings.ContainsAny(code, "_-") && code[0] >= 'A' && code[0] <= 'Z' {
562			return code
563		}
564		primary := strings.ToLower(strings.SplitN(strings.ReplaceAll(code, "-", "_"), "_", 2)[0])
565		if name, ok := languageNames[primary]; ok {
566			return name
567		}
568		return code
569	}

